<template><div class="page-container"><el-table :data="tableData" border stripe v-loading="loading"><el-table-column prop="employeeNo" label="工号"/><el-table-column prop="employeeName" label="姓名"/><el-table-column prop="deptId" label="部门ID"/><el-table-column prop="position" label="职位"/><el-table-column prop="phone" label="电话"/><el-table-column label="状态" width="70"><template #default="{row}"><el-tag :type="row.status===0?'success':'danger'" size="small">{{row.status===0?'在职':'离职'}}</el-tag></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" layout="total,prev,pager,next" @current-change="fetchData" style="margin-top:16px"/></div></template>
<script setup>import {ref,onMounted}from 'vue';import {listEmployees}from '@/api/hr';const loading=ref(false);const tableData=ref([]);const total=ref(0);const page=ref(1);onMounted(()=>fetchData());async function fetchData(){loading.value=true;try{const res=await listEmployees({page:page.value});tableData.value=res.data.records;total.value=res.data.total}finally{loading.value=false}}</script>
